function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const dispatch_ack = multisetDiff(before.dispatch_ack, after.dispatch_ack);
  const dispatch_note = multisetDiff(before.dispatch_note, after.dispatch_note);
  const dispatch_seal = multisetDiff(before.dispatch_seal, after.dispatch_seal);
  return {
    rels: [
      { rel: "dispatch_ack", add: dispatch_ack.add, del: dispatch_ack.del },
      { rel: "dispatch_note", add: dispatch_note.add, del: dispatch_note.del },
      { rel: "dispatch_seal", add: dispatch_seal.add, del: dispatch_seal.del },
    ],
    carryPending: dispatch_note.add.length > 0 || dispatch_note.del.length > 0,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) =>
      forkJoin([resolveDispatchNote_0Writes(seam, before, arrivals), resolveDispatchNote_1Writes(seam, before, arrivals)]).pipe(map((groups) => groups.flat())).pipe(
        concatMap((statements) => seam.runner.batch(seam.db, statements)),
        map(() => before),
      ),
    ),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // any_two_tagged_arms_land_on_one_tick: engine.pl process_occurrences -> level_closure -> boundary_deltas.
}

